import{_ as s,o as a,c as p,aj as e}from"./chunks/framework.BdtAaXf2.js";const l="/assets/image-20251127173418872.YESLDf74.png",i="/assets/image-20251127173428581.DaYifB6N.png",r="/assets/image-20251127173744228.DYnlAo8z.png",c="/assets/image-20251127174102177.B_Tw2NMJ.png",b="/assets/image-20251127174211799.BFzaWf_6.png",m="/assets/image-20251127174338525.DY9DWxBk.png",t="/assets/image-20251127174526447.DCuaphyN.png",u="/assets/image-20251127174601873.DpdiYaK1.png",o="/assets/image-20251127205633777.BqOPubsV.png",g="/assets/image-20251127205708406.2cqixqAK.png",d="/assets/image-20251127210442243.C06xxRo6.png",v=JSON.parse('{"title":"我是如何使用 Trae IDE 完成《流碧卡片》项目的完整记录","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/我是如何使用 Trae IDE 完成《流碧卡片》项目的完整记录/我是如何使用 Trae IDE 完成《流碧卡片》项目的完整记录.md","filePath":"AI人工智能/我是如何使用 Trae IDE 完成《流碧卡片》项目的完整记录/我是如何使用 Trae IDE 完成《流碧卡片》项目的完整记录.md","lastUpdated":1765296327000,"__rawMarkdown":"# 我是如何使用 Trae IDE 完成《流碧卡片》项目的完整记录\\n\\n## 项目背景与起点\\n\\n> 体验地址：https://card.zbztb.cn/\\n\\n这是我使用 Trae IDE + Gemini-3-pro-Preview 在 6 小时内完成的实战项目——流碧卡片（Liubi Card）。作为一个社交媒体卡片生成工具，它支持 40+ 种视觉模板，所有图片生成都在浏览器本地完成。\\n\\n**我的开发目标：**\\n- 快速验证 AI 辅助开发的可行性\\n- 实现一个完整可用的产品原型\\n- 探索 Trae IDE 的最佳实践\\n- 积累可复用的开发经验\\n\\n**最终成果：**\\n\\n- ✅ 6 小时完成从 0 到上线\\n- ✅ 40+ 精美模板系统\\n- ✅ 完整的国际化支持\\n- ✅ 深色模式适配\\n- ✅ 批量导出功能\\n\\n---\\n\\n目前项目已经部署上线，查看下效果吧。\\n\\n![image-20251127173418872](assets/image-20251127173418872.png)\\n\\n---\\n\\n![image-20251127173428581](assets/image-20251127173428581.png)\\n\\n\\n\\n\\n\\n\\n\\n## 我的实际开发历程\\n\\n### 对话一：开发一个纯Web端的卡片生成与分享平台\\n\\n在国际版Trae对话框下，输入想要实现的内容，然后利用自带的提示词优化功能，得到以下信息：\\n\\n![](assets/image-20251127173744228.png)\\n\\n```\\n开发一个纯Web端的卡片生成与分享平台，具体需求如下：\\n\\n1. 核心功能实现：\\n\\n- 开发用户输入界面，包含文本输入区域和实时预览功能\\n\\n- 实现卡片生成引擎，将用户输入的文字内容自动排版成美观的卡片布局\\n\\n- 集成HTML转图片功能，支持将生成的卡片转换为图片格式\\n\\n2. 图片处理功能：\\n\\n- 实现点击复制功能，将卡片以图片形式复制到系统剪贴板\\n\\n- 提供图片下载功能，支持PNG/JPEG格式选择\\n\\n- 确保生成的图片分辨率适配小红书和抖音的分享要求\\n\\n3. 社交平台适配：\\n\\n- 优化卡片尺寸和比例，符合小红书和抖音的内容规范\\n\\n- 添加平台分享按钮，支持一键分享到主流社交平台\\n\\n- 在图片中自动嵌入品牌水印（可选配置）\\n\\n4. 模板管理系统：\\n\\n- 开发多样化的卡片模板库，包括不同风格、配色和布局\\n\\n- 实现模板预览和选择功能\\n\\n- 允许用户自定义模板参数（颜色、字体、间距等）\\n\\n5. 技术方案建议：\\n\\n- 前端框架：React/Vue.js\\n\\n- 图片生成：html2canvas或dom-to-image\\n\\n- UI组件库：Material-UI或Ant Design\\n\\n- 状态管理：Redux或Vuex\\n\\n- 构建工具：Webpack或Vite\\n\\n6. 质量要求：\\n\\n- 响应式设计，适配移动端和桌面端\\n\\n- 生成图片清晰度高，无模糊失真\\n\\n- 操作流程流畅，用户体验良好\\n\\n- 性能优化，确保快速生成和转换\\n\\n7. 开发里程碑：\\n\\n- 第一阶段：完成基础卡片生成功能\\n\\n- 第二阶段：实现图片导出和分享功能\\n\\n- 第三阶段：开发模板管理系统\\n\\n- 第四阶段：进行多平台测试和优化\\n```\\n\\n开始执行计划，Trae比较智能，给出了具体的计划和执行步骤，就开始帮我创建项目了。\\n\\n![image-20251127174102177](assets/image-20251127174102177.png)\\n\\n其实这个执行流程结束后，我的网站已经完成了 80%功能了，不得不感叹 **gemini-3-pro-preview**的强大，昨晚使用的时候，最多也是2、3个人开始排队，大家想要体验的就抓紧了。\\n\\n![](assets/image-20251127174211799.png)\\n\\n### 对话二：修复bug\\n\\n在第一轮对话下，项目运行出出现了小许问题，我这边直接把错误提示粘贴回Trae，让它自己修复。\\n\\n![image-20251127174338525](assets/image-20251127174338525.png)\\n\\n### 对话三：为游戏/应用设计并实现一系列高品质的酷炫动态皮肤主题\\n\\n接着考虑到卡片需要酷炫的皮肤，我就开始让Trae帮我在已有的功能下添加功能。\\n\\n```\\n游戏/应用设计并实现一系列高品质的酷炫动态皮肤主题，具体要求如下：\\n\\n1. 主题清单必须包含但不仅限于：\\n\\n- 雪山主题：动态飘雪效果+冰川反光\\n\\n- 火山主题：熔岩流动+粒子喷发特效\\n\\n- 海浪主题：3D流体模拟+浪花飞溅\\n\\n- 星空主题：银河旋转+流星划过动画\\n\\n2. 技术规格：\\n\\n- 每个主题需提供4K分辨率素材\\n\\n- 支持实时动态光照效果\\n\\n- 包含环境音效配套方案\\n\\n- 适配移动端/PC端多平台渲染\\n\\n3. 视觉要求：\\n\\n- 使用HDR色彩空间\\n\\n- 粒子特效不少于3种动态元素\\n\\n- 主视觉焦点区域需有引导性动线设计\\n\\n- 所有动画循环时长控制在8-15秒区间\\n\\n4. 扩展建议：\\n\\n- 极光主题（动态光幕）\\n\\n- 量子隧道（赛博朋克风格）\\n\\n- 细胞分裂（生物科技感）\\n\\n- 数据风暴（数字粒子流）\\n\\n请确保所有皮肤主题在保持视觉冲击力的同时，系统资源占用不超过基础皮肤的120%。每个主题需提供预览缩略图、特效说明文档和技术参数表。\\n```\\n\\nTrae一口气给我整理了15个步骤，可谓是思维谨慎的boy。\\n\\n![](assets/image-20251127174526447.png)\\n\\n我也顺利得到了结果。\\n\\n![image-20251127174601873](assets/image-20251127174601873.png)\\n\\n### 对话四：修复bug:存在问题，卡片内有内容都，但是复制的图片 缺没有 卡片的文本内容\\n\\n![](assets/image-20251127205633777.png)\\n\\n### 对话5：修复bug：用了 主题，比如说雪山主题后，再修改背景颜色就无效了，我希望它有效\\n\\n![](assets/image-20251127205708406.png)\\n\\n## 后续\\n\\n考虑到后续还需要不断增加功能，其实可以利用Trae提供的SOLO功能，一步到位！\\n\\n![image-20251127210442243](assets/image-20251127210442243.png)\\n\\n后续内容也差不多，基本 **Gemini-3-pro-preview** 做到了我想要的，基本使用自然语言去理解和开发我想要的功能，这个能力的提升可以大之前一大堆优化提示词的工作都给覆盖了，果然就是遥遥领先了。\\n\\n\\n\\n最后我是利用了腾讯edgeOne把网站给部署上去了，欢迎体验。\\n\\n体验地址\\n\\n> https://card.zbztb.cn/"}'),h={name:"AI人工智能/我是如何使用 Trae IDE 完成《流碧卡片》项目的完整记录/我是如何使用 Trae IDE 完成《流碧卡片》项目的完整记录.md"};function _(T,n,D,k,I,q){return a(),p("div",null,[...n[0]||(n[0]=[e("",43)])])}const x=s(h,[["render",_]]);export{v as __pageData,x as default};
